-- Generated by the Neutrino Translator from verified MLIR.
-- Idempotent + atomic (a function body runs in a single transaction).
CREATE OR REPLACE FUNCTION attest_channel_verified_payout(p_payout_id text)
RETURNS void
LANGUAGE plpgsql
AS $$
BEGIN
    IF EXISTS (SELECT 1 FROM coordination_status WHERE idempotency_key = p_payout_id AND procedure = 'channel_verified_payout' AND reconciled) THEN
        RAISE EXCEPTION 'bad transition';
    END IF;
    INSERT INTO coordination_status(procedure, idempotency_key, attested) VALUES ('channel_verified_payout', p_payout_id, true)
    ON CONFLICT (procedure, idempotency_key) DO UPDATE SET attested = true;
END;
$$;

CREATE OR REPLACE FUNCTION execute_channel_verified_payout(p_payout_id text, p_payer_id text, p_recipient_id text, p_amount bigint, p_currency text)
RETURNS void
LANGUAGE plpgsql
AS $$
DECLARE
    -- (no computed values)
BEGIN
    IF EXISTS (SELECT 1 FROM coordination_status WHERE idempotency_key = p_payout_id AND procedure = 'channel_verified_payout' AND reconciled) THEN
        RAISE EXCEPTION 'replay';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM coordination_status WHERE idempotency_key = p_payout_id AND procedure = 'channel_verified_payout' AND attested) THEN
        RAISE EXCEPTION 'missing attestation';
    END IF;

    -- idempotency guard (replay-safe): one row per workflow key
    INSERT INTO posting_idempotency(idempotency_key, entry)
    VALUES (p_payout_id, 'channel_verified_payout')
    ON CONFLICT DO NOTHING;
    IF NOT FOUND THEN
        RETURN;  -- already processed; no double posting
    END IF;


    -- debit payer_funding (payer.funding)
    IF (p_amount) < 0 THEN
        RAISE EXCEPTION 'negative money for payer_funding';
    END IF;
    INSERT INTO ledger_balance(ledger, party, currency, balance)
    VALUES ('payer.funding', p_payer_id, p_currency, -(p_amount))
    ON CONFLICT (ledger, party, currency)
    DO UPDATE SET balance = ledger_balance.balance + (-(p_amount));
    INSERT INTO postings(procedure, entry, ledger, party, amount, currency, signed_amount, idempotency_key)
    VALUES ('channel_verified_payout', 'payer_funding', 'payer.funding', p_payer_id, p_amount, p_currency, -(p_amount), p_payout_id);

    -- credit recipient_settlement (recipient.settlement)
    IF (p_amount) < 0 THEN
        RAISE EXCEPTION 'negative money for recipient_settlement';
    END IF;
    INSERT INTO ledger_balance(ledger, party, currency, balance)
    VALUES ('recipient.settlement', p_recipient_id, p_currency, p_amount)
    ON CONFLICT (ledger, party, currency)
    DO UPDATE SET balance = ledger_balance.balance + (p_amount);
    INSERT INTO postings(procedure, entry, ledger, party, amount, currency, signed_amount, idempotency_key)
    VALUES ('channel_verified_payout', 'recipient_settlement', 'recipient.settlement', p_recipient_id, p_amount, p_currency, p_amount, p_payout_id);

    -- balanced invariant: this workflow key must net to zero
    IF (SELECT COALESCE(SUM(signed_amount), 0) FROM postings WHERE procedure = 'channel_verified_payout' AND idempotency_key = p_payout_id) <> 0 THEN
        RAISE EXCEPTION 'not balanced for %', p_payout_id;
    END IF;

    INSERT INTO coordination_status(procedure, idempotency_key, reconciled) VALUES ('channel_verified_payout', p_payout_id, true)
    ON CONFLICT (procedure, idempotency_key) DO UPDATE SET reconciled = true;
END;
$$;
